import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "पी एस ए, सी ए वन टू फाइव, सी ई ए. ये ट्यूमर मार्कर टेस्ट क्या हैं? क्या ब्लड टेस्ट से कैंसर पकड़ा जा सकता है? और रिपोर्ट हाई आए, तो क्या कैंसर पक्का है? आखिर तक देखिए.",
 "ट्यूमर मार्कर ऐसे प्रोटीन हैं, जो कुछ कैंसर सेल्स बनाते हैं, या शरीर कैंसर के जवाब में बनाता है. इन्हें ब्लड टेस्ट से मापा जाता है. पर ये कैंसर के अलावा, कई नॉर्मल या दूसरी बीमारियों में भी बढ़ सकते हैं.",
 "इनका सबसे बड़ा काम, कैंसर डायग्नोसिस के बाद, ट्रीटमेंट का असर देखना, और कैंसर लौटने पर नज़र रखना है. सिर्फ स्क्रीनिंग के लिए, कई मार्कर्स का पैनल करवाना, फायदेमंद नहीं माना जाता. एक रिपोर्ट से ज़्यादा, समय के साथ ट्रेंड ज़रूरी है.",
 "पी एस ए, पुरुषों में प्रोस्टेट से जुड़ा है. प्रोस्टेट बढ़ना, यूरिन इन्फेक्शन, प्रोस्टेटाइटिस, और कैथेटर से भी यह बढ़ सकता है. सैंपल, डॉक्टर के रेक्टल एग्ज़ाम से पहले लिया जाता है. फ्री पी एस ए, डॉक्टर को और जानकारी देता है.",
 "सी ए वन टू फाइव, महिलाओं में ओवरी के कैंसर से जुड़ा है. पर पीरियड्स, प्रेगनेंसी, एंडोमेट्रियोसिस, और लिवर या किडनी की बीमारी में भी, यह बढ़ सकता है. इसलिए हाई रिपोर्ट का मतलब, हमेशा कैंसर नहीं.",
 "सी ई ए, अक्सर आंत के कैंसर की मॉनिटरिंग में. स्मोकिंग और सूजन वाली बीमारियों में भी बढ़ सकता है. सी ए वन नाइन नाइन, पैंक्रियास और पित्त की नली के कैंसर में. पर पीलिया और पैंक्रियाटाइटिस में भी बढ़ता है, और कुछ लोगों में यह बनता ही नहीं.",
 "ए एफ पी, लिवर के कैंसर, और कुछ टेस्टिस या ओवरी के ट्यूमर में देखा जाता है. हेपेटाइटिस, सिरोसिस, और प्रेगनेंसी में भी यह हाई हो सकता है. लिवर की पुरानी बीमारी में, डॉक्टर इसे अल्ट्रासाउंड के साथ देख सकते हैं.",
 "याद रखें. नॉर्मल रिपोर्ट, कैंसर को पूरी तरह रूल आउट नहीं करती. और हाई रिपोर्ट, कैंसर का डायग्नोसिस नहीं है. डायग्नोसिस, स्कैन और बायोप्सी से होता है. फॉलो अप टेस्ट, एक ही लैब में करवाएं, और खुद से घबराएं नहीं.",
 close_voice("क्या आपने कभी कोई ट्यूमर मार्कर टेस्ट करवाया है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/tumr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/tum_{i}.wav"],check=True); f=f"/tmp/tum_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/tum_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
